// ❌ OLD: An awaited call without try/catch, or a .then() chain
// without .catch(), leaves the rejection unhandled. Since Node 15 the
// process CRASHES on unhandled rejections — a single missed catch
// (e.g. in an event handler that fires asynchronously) can take down
// the whole server.
async function load() {
  const data = await fetchData(); // ❌ OLD: no try/catch
  use(data);
}

// If fetchData() rejects, load()'s promise rejects, and if nothing
// awaits load() with a catch, the rejection is unhandled → process
// exits. Even with a global 'unhandledRejection' handler, the promise
// is still broken — the correct fix is handling at the source.

