// ✅ NEW: Handle rejections at the source — try/catch around await,
// or .catch() on the promise chain. This prevents the process crash
// and keeps error paths explicit.
async function load() {
  try {
    const data = await fetchData(); // ✅ NEW: awaited inside try
    use(data);
  } catch (err) {
    log.error('load failed', err); // ✅ NEW: handled
    // optionally: retry or fall back
  }
}

